    $sheetFinalData[$excelCounter1][6] = 'Dues From Members';            $sheetFinalData[$excelCounter1][7] = 0;            $sheetFinalData[$excelCounter1][8] = 0;            $excelCounter1++;                    }                                                                 for($i=0;$i<$diffAsset;$i++) {                $sheetFinalData[$excelCounter1][5] = '';                $sheetFinalData[$excelCounter1][6] = '';                $sheetFinalData[$excelCounter1][7] = '';                $sheetFinalData[$excelCounter1][8] = '';                $excelCounter1++;        }                                                                 $openFlag = 'Dr';        if($totalAssetTxn >= 0) {            $txnFlag = 'Dr';        } else {            $txnFlag = 'Cr';        }                                                                         $lastFlag = 'Dr';        if($forYearBalance >= 0) {            $lastFlag = 'Cr';        }        $sheetFinalData[$excelCounter1][5] = '';        $sheetFinalData[$excelCounter1][6] = '';        $sheetFinalData[$excelCounter1][7] = '';        $sheetFinalData[$excelCounter1][8] = '';        $excelCounter1++;                                                                                                                                                                          $openingPr = '';        if(!empty($totalAssetOpening)) {            $openingPr = number_format(abs($totalAssetOpening)).' '.$openFlag;        }        $txnPr = '';        if(!empty($totalAssetTxn)) {            $txnPr = number_format(abs($totalAssetTxn)).' '.$txnFlag;        }                $sheetFinalData[$excelCounter1][5] = $openingPr;        $sheetFinalData[$excelCounter1][6] = 'Total';        $sheetFinalData[$excelCounter1][7] = '';        $sheetFinalData[$excelCounter1][8] = $txnPr;                $cnt = count($sheetFinalData);                for ($i=0;$i<$cnt;$i++) {            if (!isset($sheetFinalData[$i][8])){                $sheetFinalData[$i][8] = '';            }            if (!isset($sheetFinalData[$i][3])){                $sheetFinalData[$i][3] = '';            }            if (!isset($sheetFinalData[$i][6])){                $sheetFinalData[$i][6] = '';            }            if (!isset($sheetFinalData[$i][2])){                $sheetFinalData[$i][2] = '';            }            if (!isset($sheetFinalData[$i][7])){                $sheetFinalData[$i][7] = '';            }            if (!isset($sheetFinalData[$i][1])){                $sheetFinalData[$i][1] = '';            }            if (!isset($sheetFinalData[$i][5])){                $sheetFinalData[$i][5] = '';            }            if (!isset($sheetFinalData[$i][0])){                $sheetFinalData[$i][0] = '';            }            if (!isset($sheetFinalData[$i][4])){                $sheetFinalData[$i][4] = '';            }            ksort($sheetFinalData[$i]);        }        //echo '<pre>';print_r($sheetFinalData);exit;        $this->PhpExcel->createWorksheet()->setDefaultFont('Arial', 9);        $this->PhpExcel->removeSheetByIndex(0);        $this->PhpExcel->createSheet($sheetCount);        $this->PhpExcel->getDefaultStyle()                ->getNumberFormat()                ->setFormatCode(PHPExcel_Style_NumberFormat::FORMAT_TEXT);        $this->PhpExcel->setActiveSheetIndex($sheetCount);        $this->PhpExcel->getDefaultStyle()->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_LEFT);        $this->PhpExcel->getDefaultStyle()->getAlignment()->setVertical(PHPExcel_Style_Alignment::VERTICAL_CENTER);        $this->PhpExcel->getActiveSheet()->getSheetView($sheetCount)->setZoomScale(100);        $this->PhpExcel->getActiveSheet()->freezePane('A2');        $this->PhpExcel->getActiveSheet()->setTitle('Balance Sheet');        $this->PhpExcel->getActiveSheet()->getColumnDimension('C')->setWidth(20);        $numberFormatCounter = 1;        foreach ($sheetFinalData as $sheetFinalDetails) {            foreach ($sheetFinalDetails as $ReceiptData) {                $this->PhpExcel->getActiveSheet($sheetCount)->getStyle($innerrowCounter . '1')->getFont()->setBold(true);                if ($numberFormatCounter > 3) {                    $this->PhpExcel->getActiveSheet()->getStyle($innerrowCounter . $innerColumnCounter . ":" . $innerrowCounter . $innerColumnCounter)->getNumberFormat()->setFormatCode("0.00");                }                $this->PhpExcel->getActiveSheet($sheetCount)->getStyle($innerrowCounter . $innerColumnCounter . ":" . $innerrowCounter . $innerColumnCounter)->getBorders()->getOutline()->setBorderStyle(PHPExcel_Style_Border::BORDER_THIN);                $this->PhpExcel->getActiveSheet($sheetCount)->getStyle($innerrowCounter . $innerColumnCounter . ":" . $innerrowCounter . $innerColumnCounter)->getAlignment()->setHorizontal(PHPExcel_Style_Alignment::HORIZONTAL_RIGHT);                $this->PhpExcel->setActiveSheetIndex($sheetCount)->setCellValue($innerrowCounter . $innerColumnCounter, $ReceiptData);                $innerrowCounter++;                $numberFormatCounter++;            }            $numberFormatCounter = 0;            $innerrowCounter = 'A';            $innerColumnCounter++;        }        $filename = $societyDetails['Society']['society_name'].'_'.date("Y-m-d").'_BalanceSheet';        $this->PhpExcel->output($filename . ".xlsx");        $this->PhpExcel->exit();    }        function account_income_exp_statement($isFromBalance=0,$fromDate='',$toDate='') {        $societyLoginID = $this->societyloginID;        $this->loadModel('MemberPayment');                if($isFromBalance != 1) {            $postData = $this->request->data;        }                $incomeExpensesDetails = array();        $societyDetails = $this->SocietyBill->getSocietyDetails();        //$societyMemberDetails = $this->SocietyBill->navigateSocietyMemberDetails();        if ($this->request->is(array('post')) || $isFromBalance == 1) {            $totalExpenses = 0;            $totalIncome = 0;            $totalOpeningExpenses = 0;            $totalOpeningIncome = 0;                        if($isFromBalance == 1) {                $from_date = $fromDate;                $to_date = $toDate;            } else {                $from_date = $postData['from_date'];                $to_date = $postData['to_date'];            }            $this->loadModel('SocietyLedgerHeads');            $this->loadModel('SocietyPayment');            $this->loadModel('MemberBillGenerate');            $societyLedgerHeadsObj = new SocietyLedgerHeads();                        $societyExpensesLedgerHeadsLists = $societyLedgerHeadsObj->find('all', array('conditions' => array('SocietyLedgerHeads.society_id' => $societyLoginID, 'SocietyLedgerHeads.status' => Configure::read('Active'),'SocietyLedgerHeads.account_category_id'=>4), 'order' => array('SocietyLedgerHeads.title' => 'asc')));                        $expenseHeads = array();            $incomeHeads = array();                        foreach($societyExpensesLedgerHeadsLists as $tempKey=>$tempDetails) {                $ledgerHeadDetails = $tempDetails['SocietyLedgerHeads'];                $expenseHeads[$ledgerHeadDetails['id']]['title'] = $ledgerHeadDetails['title'];                                $expenseHeads[$ledgerHeadDetails['id']]['openingAmount'] = $ledgerHeadDetails['opening_amount'];                                $totalExpenses += $ledgerHeadDetails['opening_amount'];                $totalOpeningExpenses += $ledgerHeadDetails['opening_amount'];                                        $societyPayments = $this->SocietyPayment->find('first', array('conditions' => array('SocietyPayment.ledger_head_id' => $ledgerHeadDetails['id'], 'SocietyPayment.society_id' => $societyLoginID, 'SocietyPayment.payment_date >=' => $from_date, 'SocietyPayment.payment_date <=' => $to_date),'fields' => array('sum(SocietyPayment.total_amount) as totalPaid')));                if (!empty($societyPayments)) {                    $expenseHeads[$ledgerHeadDetails['id']]['txnAmount'] += $societyPayments[0]['totalPaid'];                     $totalExpenses += $societyPayments[0]['totalPaid'];                }                                // Journal Voucher                $journalVoucherDetails = $this->JournalVoucher->find('first', array('conditions' => array('JournalVoucher.jv_debit_ledger_head_id' => $ledgerHeadDetails['id'], 'JournalVoucher.society_id' => $societyLoginID, 'JournalVoucher.voucher_date >=' => $from_date, 'JournalVoucher.voucher_date <=' => $to_date),'fields' => array('sum(JournalVoucher.jv_amount_debited) as totalDebited')));                if (!empty($journalVoucherDetails)) {                    $expenseHeads[$ledgerHeadDetails['id']]['txnAmount'] += $journalVoucherDetails[0]['totalDebited'];                     $totalExpenses += $journalVoucherDetails[0]['totalDebited'];                 }                                // Journal Voucher                $journalVoucherDetails = $this->JournalVoucher->find('first', array('conditions' => array('JournalVoucher.jv_credit_ledger_head_id' => $ledgerHeadDetails['id'], 'JournalVoucher.society_id' => $societyLoginID, 'JournalVoucher.voucher_date >=' => $from_date, 'JournalVoucher.voucher_date <=' => $to_date),'fields' => array('sum(JournalVoucher.jv_amount_credited) as totalCredited')));                if (!empty($journalVoucherDetails)) {                    $expenseHeads[$ledgerHeadDetails['id']]['txnAmount'] -= $journalVoucherDetails[0]['totalCredited'];                     $totalExpenses -= $journalVoucherDetails[0]['totalCredited'];                 }                                //Rebate                if(strtolower($ledgerHeadDetails['title']) == 'rebate') {                        $rebateBillAmount = $this->MemberBillSummary->find('first', array('conditions' => array('MemberBillSummary.society_id' => $societyLoginID, 'MemberBillSummary.bill_generated_date >=' => $from_date, 'MemberBillSummary.bill_generated_date <=' => $to_date), 'fields' => array('sum(MemberBillSummary.discount) as total_rebate')));                        if(!empty($rebateBillAmount[0]['total_rebate'])) {                            $expenseHeads[$ledgerHeadDetails['id']]['txnAmount'] += $rebateBillAmount[0]['total_rebate'];                            $totalExpenses += $rebateBillAmount[0]['total_rebate'];                        }                }            }                        $societyIncomeLedgerHeadsLists = $societyLedgerHeadsObj->find('all', array('conditions' => array('SocietyLedgerHeads.society_id' => $societyLoginID, 'SocietyLedgerHeads.status' => Configure::read('Active'),'SocietyLedgerHeads.account_category_id'=>3), 'order' => array('SocietyLedgerHeads.title' => 'asc')));                                    foreach($societyIncomeLedgerHeadsLists as $tempKey=>$tempDetails) {                $ledgerHeadDetails = $tempDetails['SocietyLedgerHeads'];                $incomeHeads[$ledgerHeadDetails['id']]['title'] = $ledgerHeadDetails['title'];                                $incomeHeads[$ledgerHeadDetails['id']]['openingAmount'] = $ledgerHeadDetails['opening_amount'];                $totalIncome += $ledgerHeadDetails['opening_amount'];                $totalOpeningIncome += $ledgerHeadDetails['opening_amount'];                                $billPayments = $this->MemberBillGenerate->find('first', array('conditions' => array('MemberBillGenerate.ledger_head_id' => $ledgerHeadDetails['id'], 'MemberBillGenerate.society_id' => $societyLoginID, 'MemberBillGenerate.bill_generated_date >=' => $from_date, 'MemberBillGenerate.bill_generated_date <=' => $to_date),'fields' => array('sum(MemberBillGenerate.amount) as totalCharge')));                if (!empty($billPayments)) {                    $incomeHeads[$ledgerHeadDetails['id']]['txnAmount'] += $billPayments[0]['totalCharge'];                     $totalIncome += $billPayments[0]['totalCharge'];                }                                  // Society other income                $SocietyOtherIncomeDetails = $this->SocietyOtherIncome->find('first', array('conditions' => array('SocietyOtherIncome.ledger_head_id' => $ledgerHeadDetails['id'], 'SocietyOtherIncome.society_id' => $societyLoginID, 'SocietyOtherIncome.payment_date >=' => $from_date, 'SocietyOtherIncome.payment_date <=' => $to_date),'fields' => array('sum(SocietyOtherIncome.amount_paid) as totalIncome')));                if (!empty($SocietyOtherIncomeDetails)) {                    $incomeHeads[$ledgerHeadDetails['id']]['txnAmount'] += $SocietyOtherIncomeDetails[0]['totalIncome'];                     $totalIncome += $SocietyOtherIncomeDetails[0]['totalIncome'];                }                                // Journal Voucher                $journalVoucherDetails = $this->JournalVoucher->find('first', array('conditions' => array('JournalVoucher.jv_credit_ledger_head_id' => $ledgerHeadDetails['id'], 'JournalVoucher.society_id' => $societyLoginID, 'JournalVoucher.voucher_date >=' => $from_date, 'JournalVoucher.voucher_date <=' => $to_date),'fields' => array('sum(JournalVoucher.jv_amount_credited) as totalCredited')));                if (!empty($journalVoucherDetails)) {                    $incomeHeads[$ledgerHeadDetails['id']]['txnAmount'] += $journalVoucherDetails[0]['totalCredited'];                     $totalIncome += $journalVoucherDetails[0]['totalCredited'];                 }                                // Journal Voucher                $journalVoucherDetails = $this->JournalVoucher->find('first', array('conditions' => array('JournalVoucher.jv_debit_ledger_head_id' => $ledgerHeadDetails['id'], 'JournalVoucher.society_id' => $societyLoginID, 'JournalVoucher.voucher_date >=' => $from_date, 'JournalVoucher.voucher_date <=' => $to_date),'fields' => array('sum(JournalVoucher.jv_amount_debited) as totalDebited')));                if (!empty($journalVoucherDetails)) {                    $incomeHeads[$ledgerHeadDetails['id']]['txnAmount'] -= $journalVoucherDetails[0]['totalDebited'];                     $totalIncome -= $journalVoucherDetails[0]['totalDebited'];                 }                                               // For Interest collection and GST collection in other income                    $ledgerHeadTitle = str_replace(' ','',$ledgerHeadDetails['title']);                                        if(strtoupper($ledgerHeadTitle) == 'INTERESTCOLLECTION') {                        $interestBillAmount = $this->MemberBillSummary->find('first', array('conditions' => array('MemberBillSummary.society_id' => $societyLoginID, 'MemberBillSummary.bill_generated_date >=' => $from_date, 'MemberBillSummary.bill_generated_date <=' => $to_date), 'fields' => array('sum(MemberBillSummary.interest_on_due_amount) as total_interest')));                        if(!empty($interestBillAmount[0]['total_interest'])) {                            $incomeHeads[$ledgerHeadDetails['id']]['txnAmount'] += $interestBillAmount[0]['total_interest'];                            $totalIncome += $interestBillAmount[0]['total_interest'];                        }                    } else if(strtoupper($ledgerHeadTitle) == 'GSTCOLLECTION') {                        //echo $from_date.'->'.$to_date;                        $taxBillAmount = $this->MemberBillGenerate->find('first', array('conditions' => array('MemberBillGenerate.society_id' => $societyLoginID, 'MemberBillGenerate.bill_generated_date >=' => $from_date, 'MemberBillGenerate.bill_generated_date <=' => $to_date), 'fields' => array('sum(MemberBillGenerate.tax_total) as total_tax')));                        //echo '<pre>'; print_r($taxBillAmount); exit;                        if(!empty($taxBillAmount[0]['total_tax'])) {                            $incomeHeads[$ledgerHeadDetails['id']]['txnAmount'] += $taxBillAmount[0]['total_tax'];                            $totalIncome += $taxBillAmount[0]['total_tax'];                        }                    }                            }        }         if($isFromBalance == 1) {            return $totalIncome-$totalExpenses;        } else {            $this->set(compact('postData', 'totalOpeningIncome', 'totalOpeningExpenses','societyDetails','totalIncome', 'totalExpenses','expenseHeads','incomeHeads'));        }        //print_r($this->request->data);die;    }    function getMembersDueAmount($memberDuesListData,$date) {                        //Opening Balance                $openingBalance = $memberDuesListData['Member']['op_principal']+$memberDuesListData['Member']['op_interest']+$memberDuesListData['Member']['op_tax'];                                //JV credited                $jvCredited = $this->JournalVoucher->find('first', array('conditions' => array('JournalVoucher.jv_credit_member_head_id'=>$memberDuesListData['Member']['id']), 'fields' => array('sum(JournalVoucher.jv_amount_credited) as totalCredited')));                $totalCredited = $jvCredited[0]['totalCredited'];                                //JV debited                $jvDebited = $this->JournalVoucher->find('first', array('conditions' => array('JournalVoucher.jv_debit_member_head_id'=>$memberDuesListData['Member']['id']), 'fields' => array('sum(JournalVoucher.jv_amount_debited) as totalDebited')));                $totalDebited = $jvDebited[0]['totalDebited'];                                //Member Payment                $totalMemberPayment = $this->MemberPayment->find('first', array('conditions' => array('MemberPayment.member_id'=>$memberDuesListData['Member']['id']), 'fields' => array('sum(MemberPayment.amount_paid) as totalPaid')));                $totalPaid = $totalMemberPayment[0]['totalPaid']+$totalCredited;                                //Member Bill Summary                $totalBillAmount = $this->MemberBillSummary->find('first', array('conditions' => array('MemberBillSummary.member_id'=>$memberDuesListData['Member']['id']), 'fields' => array('sum(MemberBillSummary.monthly_bill_amount) as totalBillAmount')));                $totalBill = $totalBillAmount[0]['totalBillAmount']+$openingBalance+$totalDebited;                                $dueAmount = $totalBill-$totalPaid;                return $dueAmount;        }            function getFirstDayFinancialYear() {        $mon = date('m');        if ($mon > 4) {            $y = date('Y');        } else {            $y = date('Y', strtotime('-1 year'));        }        return $y . "-04-01";    }}